import assert from "node:assert/strict";
import { test } from "node:test";
import { loadConfig } from "./src/config.js";

const J = (o) => JSON.stringify(o);
const mk = (files) => {
	const reads = [];
	const readFile = (p) => {
		reads.push(p);
		if (!(p in files)) throw new Error(`ENOENT ${p}`);
		return files[p];
	};
	return { readFile, reads };
};

test("R1: string and array extends, relative + absolute, normalization", () => {
	const { readFile, reads } = mk({
		"/base.json": J({ a: 1, b: 2 }),
		"/dir/app.json": J({ extends: "../base.json", b: 9, c: 3 }),
		"/dir/sub/deep.json": J({ extends: ["/base.json", "../../base.json"], d: 4 }),
	});
	assert.deepEqual(loadConfig("/dir/app.json", { readFile }), { a: 1, b: 9, c: 3 });
	assert.deepEqual(loadConfig("/dir/sub/deep.json", { readFile }), { a: 1, b: 2, d: 4 });
	// readFile called only with normalized paths; base listed twice is read once
	assert.deepEqual(reads, ["/dir/app.json", "/base.json", "/dir/sub/deep.json", "/base.json"]);
	// top-level file is normalized before reading
	const r2 = mk({ "/base.json": J({ a: 1, b: 2 }), "/dir/app.json": J({ extends: "../base.json", b: 9, c: 3 }) });
	assert.deepEqual(loadConfig("./x/../dir/app.json", { readFile: r2.readFile }), { a: 1, b: 9, c: 3 });
	assert.deepEqual(r2.reads, ["./x/../dir/app.json" === "/dir/app.json" ? "/dir/app.json" : "/dir/app.json", "/base.json"]);
	assert.deepEqual(r2.reads[0], "/dir/app.json");
});

test("R1: only a missing extends key means no bases; empty array ok; other values throw TypeError naming the file", () => {
	const good = mk({ "/a.json": J({ x: 1 }), "/b.json": J({ extends: [] }) });
	assert.deepEqual(loadConfig("/a.json", { readFile: good.readFile }), { x: 1 });
	assert.deepEqual(loadConfig("/b.json", { readFile: good.readFile }), {});
	const bad = [null, 42, {}, true, ["x", 1], [null], ["x", []]];
	for (const v of bad) {
		const m = mk({ "/a.json": J({ extends: v }) });
		assert.throws(() => loadConfig("/a.json", { readFile: m.readFile }), (e) => {
			assert.ok(e instanceof TypeError, `expected TypeError got ${e.constructor.name}`);
			assert.match(e.message, /a\.json/);
			return true;
		});
	}
});

test("R2: order of bases, later overrides earlier, own keys on top, recursive, extends excluded", () => {
	const { readFile } = mk({
