test("R7: __proto__ is an ordinary own key at any depth; prototypes untouched", () => {
	// raw JSON text: object literals with __proto__ would hit the prototype setter
	const { readFile } = mk({
		"/b.json": '{"__proto__":{"evil":true},"m":{"__proto__":"str"},"k":1}',
		"/t.json": '{"extends":"b.json","__proto__":{"good":1},"m":{"__proto__":{"x":1}}}',
	});
	const r = loadConfig("/t.json", { readFile });
	assert.equal(Object.getPrototypeOf(r), Object.prototype);
	assert.ok(Object.prototype.hasOwnProperty.call(r, "__proto__"));
