	assert.deepEqual(Object.getPrototypeOf(r.m), Object.prototype);
	assert.equal(Object.prototype.hasOwnProperty.call(r.m, "__proto__"), true);
	assert.equal(r.m.__proto__, "str"); // later non-object replaces earlier non-object
	assert.equal(r.k, 1);
	assert.equal(Object.prototype.evil, undefined);
	assert.equal(Object.prototype.good, undefined);
	// nested merged objects keep Object.prototype
	const { readFile: rf2 } = mk({
		"/b2.json": J({ m: { a: 1 } }),
