	const r2 = loadConfig("/t2.json", { readFile: rf2 });
	assert.equal(Object.getPrototypeOf(r2.m), Object.prototype);
	assert.deepEqual(r2.m, { a: 1, b: 2 });
	// top-level file with __proto__ only
	const { readFile: rf3 } = mk({ "/p.json": '{"__proto__":7}' });
	const r3 = loadConfig("/p.json", { readFile: rf3 });
	assert.ok(Object.prototype.hasOwnProperty.call(r3, "__proto__"));
	assert.equal(r3.__proto__, 7);
	assert.equal(Object.getPrototypeOf(r3), Object.prototype);
});

